def solve(s):
  n = len(s)
  if n < 2:
    return s
  dp = [[False] * n for _ in range(n)]
  for i in range(n):
    dp[i][i] = True
  max_len = 1
  start = 0
  for i in range(n - 1, -1, -1):
    for j in range(i + 1, n):
      if s[i] == s[j]:
        if j - i == 1 or dp[i + 1][j - 1]:
          dp[i][j] = True
          if j - i + 1 > max_len:
            max_len = j - i + 1
            start = i
  return s[start : start + max_len]
